-- Economics with Financial Literacy final module. Run seed_econfl_course.sql first. Safe to run more than once.

do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'economics-financial-literacy';
  if cid is null then raise exception 'Run the course file first'; end if;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 4, $j$Final Assessment: My Personal Financial Plan$j$, $j${"prompt": "Create a personal financial plan of at least 600 words and prepare a short presentation of its main ideas. Use complete sentences and label each part. Use sample numbers only and do not share private financial details. Proverbs 21:5 says, The thoughts of the diligent tend only to plenteousness; but of every one that is hasty only to want.\n\nPart 1: Economic foundations. Explain scarcity, opportunity cost and supply and demand, using one example from your own life.\nPart 2: The economy. Explain GDP, inflation, unemployment and the business cycle, and tell how inflation affects savings.\nPart 3: Career and income. Choose a career, describe the training it needs and calculate a sample net monthly income after FICA taxes of 6.2 and 1.45 percent and an estimated income tax withholding that you state.\nPart 4: Budget. Build a monthly budget with giving, saving, fixed and variable expenses.\nPart 5: Credit and debt. Explain APR, credit scores and your plan to avoid unnecessary debt, with reference to Romans 13:8 or Proverbs 22:7.\nPart 6: Saving and investing. Set one short term and one long term goal, use the rule of 72 to estimate doubling time and explain diversification.\nPart 7: Protection. Explain insurance and three ways to avoid fraud.\nPart 8: Faith and giving. Apply at least three Scriptures from the King James Version and describe your giving plan.\nPart 9: Presentation plan. List five main points you would share in a three minute talk.", "rubric": "100 points. Part 1: 10 points. Part 2: 10 points. Part 3: 10 points. Part 4: 15 points. Part 5: 10 points. Part 6: 15 points. Part 7: 10 points. Part 8: 10 points. Part 9: 5 points. Grammar, conventions and accuracy of calculations: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Final Assessment: My Personal Financial Plan$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 16, $j$Final Exam: Economics with Financial Literacy$j$, $j${"questions": [{"q": "Scarcity means:", "options": ["Wants are unlimited but resources are limited", "Markets do not exist", "Money is worthless", "Prices are too high"]}, {"q": "Opportunity cost is:", "options": ["A tax", "The sticker price", "The value of the next best alternative given up", "Profit"]}, {"q": "The law of demand says that as price rises:", "options": ["Supply stops", "Quantity demanded rises", "Wages rise", "Quantity demanded falls"]}, {"q": "A shortage occurs when the price is:", "options": ["Below equilibrium", "Zero tax", "Above equilibrium", "At equilibrium"]}, {"q": "Most nations today have a:", "options": ["Barter system only", "Pure command economy", "Mixed economy", "Traditional system only"]}, {"q": "The Federal Reserve has the goals of maximum employment and:", "options": ["Higher taxes", "Stable prices", "Lower wages", "Fewer banks"]}, {"q": "Inflation is:", "options": ["A kind of tax", "A fall in prices", "A rise in jobs", "A general rise in prices"]}, {"q": "Florida has no state:", "options": ["Personal income tax", "Court system", "Property tax", "Sales tax"]}, {"q": "The employee share of FICA includes Social Security at 6.2 percent and Medicare at:", "options": ["10 percent", "25 percent", "0.1 percent", "1.45 percent"]}, {"q": "Net pay is:", "options": ["Pay before taxes", "A loan", "Pay after deductions", "A bonus"]}, {"q": "Unit price helps you compare:", "options": ["Brand colors", "Store hours", "Price per ounce or per item", "Coupons only"]}, {"q": "A credit score usually ranges from:", "options": ["0 to 100", "300 to 850", "1 to 10", "500 to 5000"]}, {"q": "By the rule of 72, money at 8 percent doubles in about:", "options": ["9 years", "2 years", "72 years", "18 years"]}, {"q": "Romans 13:8 says:", "options": ["Trust in riches", "Borrow freely", "Owe no man any thing, but to love one another", "Spend quickly"]}, {"q": "2 Corinthians 9:7 says God loveth:", "options": ["A hidden saver", "A quick spender", "A proud lender", "A cheerful giver"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Economics with Financial Literacy$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,3,0,2,1,3,0,3,2,2,1,0,2,3}'::int[], array[$j$Scarcity is the basic economic problem.$j$,$j$Every choice gives something up.$j$,$j$Buyers buy less at higher prices.$j$,$j$Buyers want more than sellers offer.$j$,$j$Markets and government both play a role.$j$,$j$This is its dual mandate.$j$,$j$It reduces purchasing power.$j$,$j$Federal income tax still applies.$j$,$j$Employers pay a matching share.$j$,$j$Budget from net pay.$j$,$j$It shows the better value.$j$,$j$Higher scores earn better terms.$j$,$j$72 divided by 8 is 9.$j$,$j$Debt is a serious commitment.$j$,$j$Giving should come from the heart.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Economics with Financial Literacy$j$ on conflict (item_id) do nothing;
end
$seed$;
